# interface.py - interface for Robot Framework
import importlib
import os
from typing import Any, Union

from .lteue import LteUe


# CAUTION: you can't import Robot modules directly here
#          otherwise you can't use python layer "standalone" - it would always import robot as side-effect
#          any import from robot must be done inside .robot_api subpackage


def implement_by(pkg_class_name, *args, **kwargs):
    """
    Return instance of implementation class pointed by pkg_class_name

    :param pkg_class_name: implementation name in form - package.module.class
    :return: implementation class instance
    """
    pkg_module_name, class_name = pkg_class_name.rsplit('.', 1)

    module = importlib.import_module(pkg_module_name)
    klass = getattr(module, class_name)
    instance = klass(*args, **kwargs)
    return instance


class ute_ue:

    # ROBOT_LIBRARY_SCOPE class attribute must be defined here to let Robot know at module parsing time
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __new__(cls, config_path="", *args, **kwargs):
        # redirection to instantiate other class - the one that is real API for Robot
        if config_path:  # Load config from YAML for python API
            os.environ["ABSTRACT_LIB_CONFIG"] = config_path
        robot_library_instance = implement_by('ute_ue.robot_api.ute_ue', *args, **kwargs)
        robot_library_instance._python_api = bool(config_path)
        return robot_library_instance

    def get_keyword_names(self):  # if you want dynamic library then such method must appear here
        """Returns list of keywords that library provides including device specific ones"""
        pass                      # method content is ignored
        pass                      # it lets robot parser detect 'this class is dynamic library'
        pass                      # real implementation of get_keyword_names() is inside ute_ue.robot_api.ute_ue


class PythonApi:
    """
    Python Api class

    Serves as a wrapper class for starting a test suite in Python Api
    """
    def __init__(self, start=True, config_path=None):
        """
        __init__
        :param start: if true starts the test suite when the object is initialized
        :param config_path: test line configuration from a yaml file
        """
        self.ute_ue = None
        self.config_path = config_path
        if start:
            self.start()

    def start(self):
        """
        Start

        Initializes the ute_ue object and starts the test suite
        """
        self.ute_ue = ute_ue(self.config_path)
        self.ute_ue._python_api = True
        self.ute_ue.start_python_scope()

    def shutdown(self):
        """
        Shutdown

        Ends the test suite and deletes the ute_ue object
        After shutdown() is called PythonApi object is ready for another start() call
        """
        self.ute_ue.shutdown()
        del self.ute_ue
        self.ute_ue = None

    def require_ue(self, ue_alias=None, capabilities=None, keep_reservation=True, keep_reservation_timeout=120.0,
                   *args, **kwargs) -> Union[LteUe, Any]:
        """
        Find UE that fulfils given requirements and store the ue under given alias.

        :param ue_alias: Alias name assigned to the found UE - used as UE reference inside other methods of UE API.
        :param capabilities: UE capabilities requirement
        :param keep_reservation: If True, UE will be kept reserved until explicitly released
        :param keep_reservation_timeout: Timeout for keeping UE reserved (in seconds)
        :return: UE instance - LteUe child class instance: AndroidUe, AtUe, IphoneUe, MtkUe or FastmileUe
        :raises: :py:class:`ute_ue.exceptions.UeCharacteristicsIsEmpty`: If both capabilities and starting_cell are None
        :raises: :py:class:`ute_common_abstract_core.exceptions.ConfigurationNotDefined`: If UE configuration cannot be found
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if ue_alias already used for other UE
        """
        return self.ute_ue.require_ue(ue_alias=ue_alias, capabilities=capabilities,
                                      keep_reservation=keep_reservation,
                                      keep_reservation_timeout=keep_reservation_timeout, *args, **kwargs)

    def __getattr__(self, method):
        if self.ute_ue:
            try:
                return getattr(self.ute_ue, method)
            except AttributeError:
                raise NotImplementedError(f"Method {method} is not implemented!")
        else:
            raise NotImplementedError(f"Method {method} is not implemented!")
